import {api,cartId,money,esc,notice,summary} from './common.js';
const root=document.querySelector('#app');
const guarded=fn=>async event=>{try{await fn(event);}catch(error){notice(error.message);}};
async function catalog(){
 const params=new URLSearchParams(location.search);let page=Number(params.get('page')||1);
 root.innerHTML='<section class="hero"><p class="eyebrow">OBJECTS FOR EVERYDAY RITUALS</p><h1>Good things.<br>Made for your day.</h1><p>Useful, considered pieces for the places and moments you love.</p></section><form id="filters" class="filters"><label>Search the collection<input name="q" placeholder="A mug, a journal, a little joy…"></label><label>Category<select name="category"><option value="">All categories</option></select></label><button>Find your favorites</button></form><p id="count" class="muted"></p><div id="grid" class="grid"></div><nav id="paging" class="paging" aria-label="Catalog pages"></nav>';
 const form=root.querySelector('#filters');form.q.value=params.get('q')||'';
 for(const c of (await api('/categories')).items){const o=document.createElement('option');o.value=c.name;o.textContent=c.name+' ('+c.count+')';form.category.append(o);}form.category.value=params.get('category')||'';
 async function load(){const query=new URLSearchParams({page,pageSize:12});if(form.q.value.trim())query.set('q',form.q.value.trim());if(form.category.value)query.set('category',form.category.value);history.replaceState(null,'','/?'+query);const result=await api('/products?'+query);root.querySelector('#count').textContent=result.total+' thoughtful finds';root.querySelector('#grid').innerHTML=result.items.map(p=>'<article class="product"><a href="/product.html?id='+encodeURIComponent(p.id)+'"><div class="image-wrap"><img src="'+esc(p.imageUrl)+'" alt="'+esc(p.name)+'" loading="lazy">'+(!p.stock?'<span class="badge">Sold out</span>':'')+'</div><p class="eyebrow">'+esc(p.category)+'</p><h2>'+esc(p.name)+'</h2><p>'+money(p.priceCents)+'</p></a></article>').join('')||'<p>No products found. Try another search.</p>';root.querySelector('#paging').innerHTML='<button id="previous" '+(page<=1?'disabled':'')+'>← Previous</button><span>Page '+page+' of '+Math.max(1,Math.ceil(result.total/12))+'</span><button id="next" '+(page*12>=result.total?'disabled':'')+'>Next →</button>';root.querySelector('#previous').onclick=guarded(async()=>{page--;await load();});root.querySelector('#next').onclick=guarded(async()=>{page++;await load();});}
 form.onsubmit=guarded(async e=>{e.preventDefault();page=1;await load();});await load();
}
async function product(){const id=new URLSearchParams(location.search).get('id');const p=await api('/products/'+encodeURIComponent(id||''));root.innerHTML='<a class="back" href="/">← All products</a><section class="detail"><img src="'+esc(p.imageUrl)+'" alt="'+esc(p.name)+'"><div><p class="eyebrow">'+esc(p.category)+'</p><h1>'+esc(p.name)+'</h1><p class="price">'+money(p.priceCents)+'</p><p>'+esc(p.description)+'</p><p class="muted">'+p.stock+' in stock</p><form id="add"><label>Quantity<input name="quantity" type="number" min="1" max="'+Math.min(99,p.stock)+'" value="1" required></label><button '+(!p.stock?'disabled':'')+'>'+(p.stock?'Add to cart':'Sold out')+'</button></form><a href="/cart.html">View your cart →</a></div></section>';root.querySelector('#add').onsubmit=guarded(async e=>{e.preventDefault();const cart=await cartId();await api('/carts/'+cart+'/items','POST',{productId:p.id,quantity:Number(e.target.quantity.value)});notice('Added to your cart.');});}
async function cart(){const id=await cartId();async function render(){const c=await api('/carts/'+id);root.innerHTML='<p class="eyebrow">YOUR FINDS</p><h1>A little collection<br>of good things.</h1><div class="cart-layout"><section><div class="lines">'+(c.items.map(item=>'<article class="cart-line"><div><a href="/product.html?id='+encodeURIComponent(item.productId)+'"><h2>'+esc(item.name)+'</h2></a><p>'+money(item.priceCents)+' each</p></div><label>Quantity<input aria-label="Quantity for '+esc(item.name)+'" data-quantity="'+esc(item.productId)+'" type="number" min="0" max="99" value="'+item.quantity+'"></label><b>'+money(item.lineTotalCents)+'</b><button class="subtle" data-remove="'+esc(item.productId)+'">Remove</button></article>').join('')||'<p>Your cart is waiting for something lovely. <a href="/">Explore the collection →</a></p>')+'</div></section><aside><h2>Order summary</h2>'+summary(c)+'<form id="discount"><label>Discount code<input name="code" placeholder="Try WELCOME10" value="'+esc(c.discountCode||'')+'"></label><button class="secondary">Apply code</button></form>'+(c.discountCode?'<button id="clear" class="subtle">Remove discount</button>':'')+'<a class="button" href="/checkout.html">Continue to checkout →</a></aside></div>';for(const input of root.querySelectorAll('[data-quantity]'))input.onchange=guarded(async()=>{await api('/carts/'+id+'/items/'+encodeURIComponent(input.dataset.quantity),'PATCH',{quantity:Number(input.value)});await render();});for(const button of root.querySelectorAll('[data-remove]'))button.onclick=guarded(async()=>{await api('/carts/'+id+'/items/'+encodeURIComponent(button.dataset.remove),'DELETE');await render();});root.querySelector('#discount').onsubmit=guarded(async e=>{e.preventDefault();await api('/carts/'+id+'/discount','POST',{code:e.target.code.value.trim()});await render();notice('Discount applied.');});if(root.querySelector('#clear'))root.querySelector('#clear').onclick=guarded(async()=>{await api('/carts/'+id+'/discount','DELETE');await render();});}await render();}
async function checkout(){const id=await cartId();const c=await api('/carts/'+id);root.innerHTML='<p class="eyebrow">ONE LAST THING</p><h1>Make it yours.</h1><div class="cart-layout"><section><h2>Your details</h2><form id="checkout"><label>Email address<input name="email" type="email" autocomplete="email" placeholder="you@example.com" required></label><p class="muted">Your order will be saved securely in our store.</p><button '+(!c.items.length?'disabled':'')+'>Place order · '+money(c.totalCents)+'</button></form>'+(!c.items.length?'<p>Your cart is empty. <a href="/">Start exploring →</a></p>':'')+'</section><aside><h2>Order summary</h2>'+c.items.map(i=>'<p>'+esc(i.name)+' × '+i.quantity+' <b>'+money(i.lineTotalCents)+'</b></p>').join('')+summary(c)+'</aside></div>';root.querySelector('#checkout').onsubmit=guarded(async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const order=await api('/checkout','POST',{cartId:id,email:e.target.email.value});localStorage.removeItem('shop.cart');root.innerHTML='<section class="success"><p class="eyebrow">THANK YOU</p><h1>Good things<br>are on their way.</h1><p>Your order is confirmed.</p><p>Order id: <strong id="order-id">'+esc(order.id)+'</strong></p><p>Total '+money(order.totalCents)+'</p><a class="button" href="/">Back to the collection →</a></section>';notice('Order placed successfully.');}catch(error){button.disabled=false;throw error;}});}
const page=document.body.dataset.page;guarded(async()=>{await ({catalog,product,cart,checkout}[page]||catalog)();})({});

export const money=cents=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100);
export const esc=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
export async function api(path,method='GET',body){const response=await fetch('/api'+path,{method,headers:{'content-type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const value=await response.json();if(!response.ok)throw new Error(value.error?.message||'Request failed');return value;}
export async function cartId(){let id=localStorage.getItem('shop.cart');if(id){try{await api('/carts/'+id);return id;}catch(error){localStorage.removeItem('shop.cart');}}id=(await api('/carts','POST')).id;localStorage.setItem('shop.cart',id);return id;}
export function notice(message){document.querySelector('#notice').textContent=message;}
export function summary(cart){return '<div class="totals"><p>Subtotal <b>'+money(cart.subtotalCents)+'</b></p><p>Discount <b>−'+money(cart.discountCents)+'</b></p><p>Tax · 8% <b>'+money(cart.taxCents)+'</b></p><p class="grand">Total <b>'+money(cart.totalCents)+'</b></p></div>';}

import {test,before} from 'node:test';
import assert from 'node:assert/strict';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
import {fixture} from './helpers.js';
before(async()=>{await promisify(execFile)(process.execPath,['build.mjs'],{timeout:20000});});
test('built pages, JavaScript and CSS are served',async t=>{
 const {base}=await fixture(t);
 for(const path of ['/','/product.html?id=mug-classic','/cart.html','/checkout.html']){const r=await fetch(base+path);assert.equal(r.status,200);assert.match(await r.text(),/id="app"/);}
 for(const path of ['/app.js','/style.css']){const r=await fetch(base+path);assert.equal(r.status,200);assert.ok((await r.text()).length>100);}
});
